import{_ as t}from"./chunks/safety-distance.DrDRmnVq.js";import{_ as s,o as n,c as r,a5 as e}from"./chunks/framework.CcrBcQWS.js";const f=JSON.parse('{"title":"일반 안전 지침","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/manual/safety/general-safety-warning-precautions.md","filePath":"ko/manual/safety/general-safety-warning-precautions.md","lastUpdated":1787021357000}'),o={name:"ko/manual/safety/general-safety-warning-precautions.md"};function i(l,a,g,c,d,u){return n(),r("div",null,[...a[0]||(a[0]=[e('<h1 id="일반-안전-지침" tabindex="-1">일반 안전 지침 <a class="header-anchor" href="#일반-안전-지침" aria-label="Permalink to &quot;일반 안전 지침&quot;">​</a></h1><p>RBQ를 안전하게 사용하기 위해 반드시 지켜야 할 일반적인 안전 지침입니다. 경고·주의 기호 의미는 <a href="/RBQ/nightly/ko/manual/safety/indications.html">안전 표시</a>를 참고하세요.</p><h2 id="일반-원칙" tabindex="-1">일반 원칙 <a class="header-anchor" href="#일반-원칙" aria-label="Permalink to &quot;일반 원칙&quot;">​</a></h2><ul><li>RBQ는 <strong>부착물을 실을 수 있고</strong> 부착물에 <strong>전원을 공급</strong>할 수 있습니다. 부착물은 무게·형상에 따라 로봇의 안정성과 에너지 소비에 영향을 줍니다.</li><li>RBQ는 <strong>동적 기계</strong>이므로, 지형·바닥·장애물 등 현장 조건에 따라 <strong>예기치 않은 움직임</strong>이 발생할 수 있습니다. 이상 징후 시 즉시 비상 정지하고 원인을 확인하세요.</li></ul><div class="sb sb-caution"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">주의</p><p> RBQ의 동작은 동적이며, 지형·바닥 상태·장애물 등 로컬 조건에 따라 예기치 않은 동작이 발생할 수 있습니다. 이상 징후 시 즉시 비상 정지하고 원인을 확인하세요. </p></div></div><h2 id="운용-전-준비" tabindex="-1">운용 전 준비 <a class="header-anchor" href="#운용-전-준비" aria-label="Permalink to &quot;운용 전 준비&quot;">​</a></h2><ul><li><strong>교육받은 조작자</strong>: 로봇은 <strong>해당 매뉴얼과 안전 교육을 이수한 조작자</strong>가 조작해야 합니다. 로봇 사용 전 매뉴얼을 숙지하고, 운용·안전 교육을 이수하세요.</li><li><strong>작업 공간</strong>: 로봇이 이동·자세 보정·넘어짐 복구를 할 수 있는 <strong>충분한 여유 공간</strong>을 확보하고, 주변에 위험물을 두지 마세요. 좁고 복잡한 환경에서는 보정 동작으로 인해 예상과 다른 방향으로 움직일 수 있으므로, 필요 시 가드 설치를 검토하세요.</li></ul><figure><img src="'+t+'" alt="작업 시 충분한 여유 공간 확보 및 가드 검토"><figcaption style="text-align:center;">[ 작업 공간은 여유를 두고, 필요 시 가드 설치를 검토하세요. ]</figcaption></figure><h2 id="운용-중" tabindex="-1">운용 중 <a class="header-anchor" href="#운용-중" aria-label="Permalink to &quot;운용 중&quot;">​</a></h2><div class="sb sb-danger"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">위험</p><p><strong>운용 중에는 로봇 반경 2m 안에 사람·동물(반려동물 포함)·기타 생명체가 들어오면 안 됩니다.</strong> 로봇이 움직이는 동안 해당 구역으로의 진입을 금지하고, 로봇에 손대지 마세요.</p></div></div><ul><li><strong>비상 정지</strong>: <a href="/RBQ/nightly/ko/manual/safety/emergency-stop-procedures.html">비상 정지 절차</a>를 참고하세요.</li><li><strong>접근 금지</strong>: 로봇 반경 2m 이내에는 사람, 동물(강아지 등 반려동물 포함)이 들어오면 안 됩니다. 동작 범위 안으로 들어가거나 로봇에 손을 대지 마세요.</li><li><strong>설정 확인</strong>: 설치 각도, 툴·안전 설정 등이 올바른지 정기적으로 확인하세요.</li></ul><h2 id="장비-및-개조" tabindex="-1">장비 및 개조 <a class="header-anchor" href="#장비-및-개조" aria-label="Permalink to &quot;장비 및 개조&quot;">​</a></h2><ul><li><strong>안전 I/O</strong>: 안전 관련 장비는 반드시 안전 전용 I/O 포트에만 연결하세요. 일반용 I/O에 연결하지 마세요.</li><li><strong>무단 개조 금지</strong>: Rainbow Robotics의 지원 없이 로봇을 개조하지 마세요. 무단 개조로 인한 손해는 사용자 책임입니다.</li></ul><h2 id="열·전기" tabindex="-1">열·전기 <a class="header-anchor" href="#열·전기" aria-label="Permalink to &quot;열·전기&quot;">​</a></h2><ul><li><strong>열 주의</strong>: 장시간 사용 시 로봇과 제어기는 뜨거워질 수 있습니다. 식힌 후에만 접촉하세요.</li><li><strong>전기 안전</strong>: 전기 관련 주의사항은 <a href="/RBQ/nightly/ko/manual/safety/electrical-safety.html">전기 안전</a>을 참고하세요.</li></ul><h2 id="일반-경고" tabindex="-1">일반 경고 <a class="header-anchor" href="#일반-경고" aria-label="Permalink to &quot;일반 경고&quot;">​</a></h2><ul><li><strong>부착물</strong>: 부착물은 로봇의 안정성과 에너지 소비에 영향을 줍니다. 부착 시 무게·형상에 따른 위험을 평가하세요.</li><li><strong>장애물</strong>: 장애물이 갑자기 나타나면 회피·보정 동작으로 <strong>예상과 다른 방향으로 가속</strong>할 수 있습니다. 주변 여유 공간을 확보하세요.</li><li><strong>계단·불규칙한 표면</strong>: 계단이나 고르지 않은 바닥에서는 자세를 급격히 바꿀 수 있습니다. 해당 구역에서는 속도·접근 방식을 제한하세요.</li><li><strong>과거 성능</strong>: 이전에 문제없이 동작했다고 해서 이후에도 동일한 조건에서 같은 성능이 보장되는 것은 아닙니다. 정기적으로 환경·설정을 확인하세요.</li></ul>',17)])])}const m=s(o,[["render",i]]);export{f as __pageData,m as default};
